\[
\begin{aligned}
    \mathscr{W}_7 := \sum_{\substack{s_1, s_2 \sim S \\ (s_1 s_2, a) = 1}} \lambda'_{s_1} \overline{\lambda'_{s_2}}
    \sum_{\substack{h_1, h_2 \\ \ell = h_1 s_1 - h_2 s_2 \neq 0}} \phi(h_1, h_2)
    \sum_{f} \Psi_0\left(\frac{f}{F}\right)
    \sum_{(c, s_1s_2) = 1} \Psi_0\left(\frac{c}{C}\right)
    \sum_{x \in (\mathbb{Z}/c\mathbb{Z})^\times}
    e\left(\frac{a\ell \overline{s_1s_2 x}}{c}\right)
    \\
    \times 
    \frac{B}{C} \Psi_0\left(\frac{uc}{C}\right) \sum_k \Psi\left(\frac{|k|}{K}\right) e\left(-k\frac{uB}{C}\right) e\left(\frac{xfk}{c}\right).
\end{aligned}
\]
We first bound $\mathscr{W}_6$ using the Ramanujan sum bound (see \cref{lem:weil}), \cref{eq:bcf-bounds,eq:cf-substitution}:
\begin{equation} \label{eq:W6-bound}
\begin{aligned}
    \mathscr{W}_6 
    &=
    \sum_{\substack{s_1, s_2 \sim S \\ (s_1 s_2, a) = 1}} \lambda'_{s_1} \overline{\lambda'_{s_2}}
    \sum_{h_1, h_2} \phi(h_1, h_2)
    \sum_{f} \Psi_0\left(\frac{f}{F}\right)
    \sum_{(c, s_1s_2) = 1} \Psi_0\left(\frac{c}{C}\right)
    S(0, a\ell; c)
    \frac{B}{c} \widehat{\Psi_0}(0)
    \\
    &\ll
    \sum_{s_1, s_2 \sim S}
    \sum_{h_1, h_2 \asymp H}
    \sum_{f \asymp F}
    \sum_{c \asymp C}
    (a\ell, c)
    \frac{B}{c}
    \\
    &\ll_a 
    x^{o(1)} S^2 H^2 F B
    \\
    &\ll 
    x^{o(1)} S^2 \left(\frac{QR^2 S^2}{x/N}\right)^2 \frac{N}{dQ} NR 
    \ll_\varepsilon 
    x^\varepsilon \frac{Q R^5 S^6 N^4}{dx^2}.
\end{aligned}
\end{equation}
This is acceptable in \cref{eq:W5-bound-to-show} (i.e., $\ll_\varepsilon x^{-7\varepsilon} N^2 R^2 S^3/d$) provided that
\[
    N^2 Q R^3 S^3 \ll x^{2-8\varepsilon},
\]
which follows from $Q \ll N$ and the first and third assumptions in \cref{eq:ranges-qrs}:
\[
\begin{aligned}
    N^2 Q R^3 S^3 
    &\ll N^3 R^3 S^3 
    \\
    &\le 
    \left(N^2 R^2 S\right)^{4/3} \cdot \left(N R^2 S^5\right)^{1/3}
    \le
    \left(x^{1-8\varepsilon}\right)^{4/3} \left(x^{2-32\varepsilon}\right)^{1/3}
    <
    x^{2-8\varepsilon}.
\end{aligned}
\]
We are left to consider $\mathscr{W}_7$, which roughly corresponds to the sum in \cref{eq:sum-kloosterman-overview}, and can be rewritten as
\[
\begin{aligned}
    \mathscr{W}_7 = \frac{B}{C} \sum_{\substack{s_1, s_2 \sim S \\ (s_1 s_2, a) = 1}} \lambda'_{s_1} \overline{\lambda'_{s_2}}
    \sum_{f,k} \Psi_0\left(\frac{f}{F}\right)
    \Psi\left(\frac{|k|}{K}\right) e\left(-k\frac{uB}{C}\right)
    \sum_{\substack{h_1, h_2 \\ \ell = h_1 s_1 - h_2 s_2 \neq 0}} \phi(h_1, h_2)
    \\
    \times 
    \sum_{(c, s_1s_2) = 1}
    \Psi_0\left(\frac{c}{C}\right) \Psi_0\left(\frac{uc}{C}\right)
    S(fk\overline{s_1 s_2}, a\ell; c).
\end{aligned}
\]
We can now apply \cref{lem:consequence-Kloosterman} with the smooth weight
\[
    \Phi\left(x_1, x_2, z\right) := \Psi_0\left(x_1\right)
    \Psi\left(x_2\right) e\left(\mp x_2\frac{uKB}{C}\right)  \Psi_0\left(z\right) \Psi_0\left(uz\right),
\]
once for each choice of the $\pm$ sign (corresponding to the sign of $k$; note that $S(-fk\overline{s_1 s_2}, a\ell; c) = S(fk\overline{s_1 s_2}, -a\ell; c)$, so one can transfer the sign change to $a$ without loss of generality). This $\Phi$ is compactly supported and satisfies $\partial_{x_1}^{j_1} \partial_{x_2}^{j_2} \partial_z^\ell \Phi(x_1, x_2, z) \ll_{j_1,j_2,k,\ell} (KB/C)^{j_2} \ll x^{o(j_2)}$, where we used $K \ll x^{o(1)} B^{-1} C$ by \cref{eq:W-off-diagonal-split}. Since $\theta_{\max} \le \tfrac{7}{32} = \theta$, we can bound
\[
\begin{aligned}
    \mathscr{W}_7 &\ll_a x^{o(1)} \frac{B}{C} 
    \left(1 + \frac{C\sqrt{F}}{S^2\sqrt{\frac{H^2}{H+S}}}\right)^{\theta} 
    \\
    &\times
    \sqrt{H^2S^3 (H + S) F K}
    \left(\frac{C^2}{S}\left(FK + S^2\right)\left(H + S\right) + FKHS\right)^{1/2}.
\end{aligned}
\]
At this point we note that by \cref{eq:ranges-qrs},
\[
    H \le x^{o(1)} \frac{NQ R^2 S^2}{x} 
    \ll 
    x^{o(1)}
    \frac{N^2 R^2 S}{x} S 
    \ll 
    x^{o(1)} S.
\]
Using this and the fact that $K \ll x^{o(1)} B^{-1} C$ from \cref{eq:W-off-diagonal-split}, our bound for $\mathscr{W}_7$ simplifies to
\[
\begin{aligned}
    \mathscr{W}_7 &\ll_a x^{o(1)} \frac{B}{C} 
    \left(1 + \frac{C\sqrt{F}}{S^{3/2} H}\right)^{\theta} 
    \sqrt{H^2S^4 F C / B}
    \left(C^2\left(FC/B + S^2\right) + FCHS/B\right)^{1/2}
    \\
    &\ll 
    x^{o(1)} 
    \left(1 + \frac{C\sqrt{F}}{S^{3/2} H}\right)^{\theta} 
    \sqrt{H^2S^4 F}
    \left(C\left(FC + BS^2\right) + FHS\right)^{1/2}.
\end{aligned}
\]
Plugging in the bounds for $B, C, F$ from \cref{eq:cf-substitution} and \cref{eq:bcf-bounds}, we are left with
\[
\begin{aligned}
    \mathscr{W}_7
    &\ll_a \frac{x^{o(1)}}{d}
    \left(1 + \frac{C_0\sqrt{F_0}}{S^{3/2} H}\right)^{\theta} 
    \sqrt{H^2S^4 F}
    \left(C_0\left(FC + BS^2\right) + F_0HS\right)^{1/2}
    \\
    &\ll_a 
    \frac{x^{o(1)}}{d}
    \left(1 + \frac{NRS \sqrt{N/Q}}{S^{3/2} H}\right)^{\theta} 
    \sqrt{H^2S^4N/Q}
    \left(NRS \left((N/Q)NRS + NRS^2\right) + (N/Q)HS\right)^{1/2}
    \\
    &= 
    \frac{x^{o(1)}}{d}
    \left(1 + \frac{N^{3/2} R}{H \sqrt{SQ}}\right)^{\theta} 
    \frac{H S^{5/2} N}{Q}
    \left(NR^2S \left(N + QS\right) + H\right)^{1/2}.
\end{aligned}
\]
Finally, noting that the right-hand side is increasing in $H \le x^{o(1)} NQR^2 S^2/x$, we get
\[
\begin{aligned}
    \mathscr{W}_7 
    &\ll_a \frac{x^{o(1)}}{d}
    \left(1 + \frac{x\sqrt{N}}{R S^{5/2} Q^{3/2}}\right)^{\theta} 
    \frac{N^2R^2S^{9/2}}{x}
    \left(N^2R^2S + NQR^2S^2 + \frac{NQR^2 S^2}{x}\right)^{1/2}
    \\
    &\ll_a
    \frac{x^{o(1)}}{d}
    \left(1 + \frac{x\sqrt{N}}{R S^{5/2} Q^{3/2}}\right)^{\theta} 
    \frac{N^{5/2} R^3 S^5}{x}
    \left(N + QS\right)^{1/2}
    \\
    &\ll_{\varepsilon,a} 
    \frac{x^\varepsilon}{d}
    \left(\frac{N^3 R^3 S^5}{x} \left(1 + \left(\frac{x\sqrt{N}}{R S^{5/2}} \right)^{\theta}\right) + \frac{N^{5/2} Q^{1/2} R^3 S^{11/2}}{x} \left(1 + \left(\frac{x\sqrt{N}}{R S^{5/2} Q^{3/2}} \right)^{\theta}\right)\right),
\end{aligned}
\]
where we omitted a factor of $Q^{-3\theta/2}$ in the second term of the expansion.
For this to be acceptable in \cref{eq:W5-bound-to-show} (i.e., $\ll_{\varepsilon,a} x^{-7\varepsilon} N^2 R^2 S^3 / d$), we need the following restrictions:
\[
\begin{gathered}
    N R S^2 \ll x^{1-8\varepsilon},
    \qquad\qquad
    N^{2+\theta} R^{2-2\theta} S^{4-5\theta}
    \ll 
    x^{2-2\theta-16\varepsilon},
    \\
    N Q R^2 S^5 \ll x^{2-16\varepsilon},
    \qquad\qquad 
    N^{1+\theta} Q^{1-3\theta} R^{2-2\theta} S^{5-5\theta} \ll 
    x^{2-2\theta-16\varepsilon}.
\end{gathered}
\]
All of these restrictions follow from \cref{eq:ranges-qrs}, $Q \ll N$, and $\theta \le 1/2$, as shown below:
\[
\begin{aligned}
    NRS^2 &\le \left(N^2 R^2 S \cdot N R^2 S^5 \right)^{1/3}
    \le 
    \left(x^{1-8\varepsilon} \cdot x^{2-32\varepsilon}\right)^{1/3}
    < 
    x^{1-8\varepsilon},
    \\
    N Q R^2 S^5
    &\ll 
    \left(\frac{N}{Q}\right)^{\frac{2\theta}{1-\theta}} N Q R^2 S^5
    =
    N^{\frac{1+\theta}{1-\theta}} Q^{\frac{1-3\theta}{1-\theta}} R^2 S^5
    < 
    x^{2-16\varepsilon},
    \\
    N^{2+\theta} R^{2-2\theta} S^{4-5\theta} 
    &= 
    \left(N^{\frac{2+\theta}{2-2\theta}} R S^{\frac{4-5\theta}{2-2\theta}}\right)^{2-2\theta}
    \le 
    (x^{1-16\varepsilon})^{2-2\theta}
    \le 
    x^{2-2\theta-16\varepsilon},
    \\
    N^{1+\theta} Q^{1-3\theta} R^{2-2\theta} S^{5-5\theta}
    &= 
    \left(N^{\frac{1+\theta}{1-\theta}} Q^{\frac{1-3\theta}{1-\theta}} R^{2} S^5\right)^{1-\theta}
    \le 
    (x^{2-32\varepsilon})^{1-\theta}
    \le 
    x^{2-2\theta-16\varepsilon}.
\end{aligned}
\]
In light of \cref{eq:W5-split,eq:W-diagonal-bound,eq:W-off-diagonal-split,eq:W6-bound}, this establishes \cref{eq:W5-bound-to-show} and completes our proof.

